INSERT INTO feature VALUES('text-primitives','types','Text, pattern and path primitives','native-primitives','partial','ordinary',NULL,'Text primitives on the machine: `string.append` writes the first string then the second, checked at its prelude signature and run on both executors, and an interpolated string `"…${ e }…"` lowers to its appends in written order and prints back as itself; `string.eq` compares two strings byte for byte, and `a == b` between strings resolves the prelude''s `EqString` model of `Eq` to it (#1832), two operands no model of `Eq` carries refused by name; `string.lt` orders two strings by their bytes, lexicographically, and `<`, `<=`, `>` and `>=` between strings resolve the prelude''s `OrdString` model of `Ord`, built on `EqString`, while between integers they resolve `OrdInteger`, the integer primitives (#2333); string escaping and scanning, regular-expression extraction and path primitives are still to come.','core-term runtime-emitter surface-lowering surface-pretty','corpus/model/builtins/simple-builtins.gandr corpus/model/builtins/strings.gandr corpus/model/modules/model-ord.gandr corpus/surface/string-interpolation.gandr crates/runtime-emitter/tests/forms.rs','corpus/ledger/features/text-primitives.gandr','#318 #1505');
